insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status) select u.id, 7, 9, 'CORE', 'text', null, $j${"k":"text","text":"Tom and Ken are at a store.\nTom looks at some shorts. Ken looks at a hat.\nThe shorts are fifteen thousand won. The hat is ten thousand won.\nTom says, \"These shorts are nice.\"\nKen says, \"This hat is cheap.\"","ko":"톰과 켄이 가게에 있어. 톰은 반바지를, 켄은 모자를 봐. 반바지는 15,000원, 모자는 10,000원이야. 톰은 \"이 반바지 멋지다.\"라고, 켄은 \"이 모자는 싸다.\"라고 해.","test":true}$j$::jsonb, 'approved' from units u join books b on b.id=u.book_id where b.title='비상교육 초5 영어' and u.no=9;
